"""Write src/scrub-meta.ts from public/scrub/*.json (grid geometry of each scrub sprite)."""
import json, pathlib
root = pathlib.Path(__file__).resolve().parent.parent
entries = []
for f in sorted((root / "public/scrub").glob("*.json")):
    m = json.loads(f.read_text())
    entries.append(f'  "{f.stem}": {{ count: {m["count"]}, cols: {m["cols"]}, rows: {m["rows"]}, w: {m["w"]}, h: {m["h"]} }},')
(root / "src/scrub-meta.ts").write_text(
    "// Generated by scripts/scrub-meta.py. Grid geometry of each sprite in public/scrub.\n"
    "export type SpriteMeta = { count: number; cols: number; rows: number; w: number; h: number };\n\n"
    "export const SCRUB: Record<string, SpriteMeta> = {\n" + "\n".join(entries) + "\n};\n")
print(len(entries), "sprites")
